// Command gen-tutorial-fragments is a GEN-TIME tool (mirrors
// cmd/gen-home-fragments — see that command's package doc for the full
// rationale) that renders the Portal Tutorial tab's chapter content from
// source markdown into sanitized, fixed HTML and writes it as a committed
// Go source file (internal/scoreboard/view/tutorialfragments_gen.go). The
// scoreboard binary go:embeds that generated file's string constants at
// compile time and never runs markdown parsing or HTML sanitization itself
// — see internal/homefragments's package doc for why this split exists.
//
// Usage:
//
//	go run ./cmd/gen-tutorial-fragments <repo-root>
//
// Wired to `make gen-tutorial-fragments` (Dockerfile.gen-tutorial-fragments,
// mirroring Dockerfile.gen-home-fragments's export-stage pattern). Commit
// the generated output; there is no CI diff-check for this generator yet
// (same known gap as gen-home-fragments — not blocking for P24).
//
// Unlike gen-home-fragments, this command has no per-challenge scan step:
// docs-site/tutorial-chapters.yaml (internal/homefragments.TutorialChapters)
// is entirely static, non-per-challenge content (REFACTORING.md P24
// architect decision §1) — every chapter is rendered the SAME way
// (RenderStaticPanel), in manifest order, with no ChalNN concept at all.
//
// Fail-soft policy (tutorial-chapters.yaml): a missing source file or a
// missing heading section is NOT an error — that chapter panel is simply
// omitted from the generated output. The only FATAL condition is a
// markdown/HTML render step itself erroring (a pipeline bug, not absent
// content) or a manifest authoring bug (a heading selector missing its "#"
// prefix — see homefragments.RenderStaticPanel's doc).
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"

	"github.com/Qfour/falco-ctf-app/internal/homefragments"
)

type chapter struct {
	ID    string // Go identifier-safe key, e.g. "intro", "condition_reading"
	Label string
	HTML  string
}

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: gen-tutorial-fragments <repo-root>")
		os.Exit(2)
	}
	root := os.Args[1]

	var chapters []chapter

	for _, sp := range homefragments.TutorialChapters {
		html, ok, err := homefragments.RenderStaticPanel(root, sp)
		if err != nil {
			fmt.Fprintf(os.Stderr, "gen-tutorial-fragments: FATAL rendering chapter %s: %v\n", sp.ID, err)
			os.Exit(1)
		}
		if !ok {
			fmt.Fprintf(os.Stderr, "gen-tutorial-fragments: omitting chapter %s (source/heading not found — fail-soft)\n", sp.ID)
			continue
		}
		chapters = append(chapters, chapter{ID: goIdent(sp.ID), Label: sp.Label, HTML: html})
	}

	out, err := generateGoSource(chapters)
	if err != nil {
		fmt.Fprintf(os.Stderr, "gen-tutorial-fragments: FATAL generating Go source: %v\n", err)
		os.Exit(1)
	}

	destDir := filepath.Join(root, "internal", "scoreboard", "view")
	dest := filepath.Join(destDir, "tutorialfragments_gen.go")
	if err := os.WriteFile(dest, []byte(out), 0o644); err != nil {
		fmt.Fprintf(os.Stderr, "gen-tutorial-fragments: FATAL writing %s: %v\n", dest, err)
		os.Exit(1)
	}
	fmt.Printf("gen-tutorial-fragments: wrote %s (%d chapters)\n", dest, len(chapters))
}

var nonIdentRe = regexp.MustCompile(`[^a-zA-Z0-9]+`)

func goIdent(s string) string {
	return strings.Trim(nonIdentRe.ReplaceAllString(s, "_"), "_")
}

func generateGoSource(chapters []chapter) (string, error) {
	var b strings.Builder
	b.WriteString(`// Code generated by cmd/gen-tutorial-fragments from docs-site/
// tutorial-chapters.yaml sources. DO NOT EDIT BY HAND — re-run
// 'make gen-tutorial-fragments'.
//
// Every TutorialFragment.HTML value below has already been through
// internal/homefragments' gen-time markdown->HTML->sanitize pipeline (the
// SAME pipeline homefragments_gen.go's HomeFragment.HTML values go
// through — see homefragments.RenderStaticPanel): it contains ONLY
// elements from the sanitize allowlist, with zero attributes on any
// element. The scoreboard binary trusts this file's content verbatim at
// render time (see portal.go's Tutorial pane wiring) BECAUSE it was
// produced by that pipeline, not because runtime code re-sanitizes it —
// there is no runtime sanitizer; re-running this generator is the only way
// this file's content changes.

package view

// TutorialFragment is one sanitized content chapter for the Portal
// Tutorial tab. Unlike HomeFragment, there is no ChalNN field: every
// Tutorial chapter is static, non-per-challenge content (REFACTORING.md
// P24 architect decision §1) — the Tutorial tab has no per-challenge
// concept at all.
type TutorialFragment struct {
	ID    string
	Label string
	HTML  string
}

// TutorialFragments is every gen-time-rendered Tutorial chapter, in
// curriculum (manifest) order. A missing source file or heading section
// simply has no entry here — fail-soft, per tutorial-chapters.yaml; the
// Tutorial pane must not synthesize a placeholder for a missing entry.
var TutorialFragments = []TutorialFragment{
`)
	for _, c := range chapters {
		fmt.Fprintf(&b, "\t{ID: %s, Label: %s, HTML: %s},\n",
			strconv.Quote(c.ID), strconv.Quote(c.Label), strconv.Quote(c.HTML))
	}
	b.WriteString("}\n")
	return b.String(), nil
}
